import { expect, test } from 'bun:test';
import { Parser } from '../src/parser/parser';
import { ASTBuilder } from '../src/ast/astBuilder';
import { validateAST } from '../src/ast/astValidator';
import { buildGame } from '../src/game/builder/builder';
import { createEngine } from '../src/game/game';
import { createEvaluator } from '../src/game/interpreter/interpreter';
import { PRESETS } from '../src/frontend/presets';
import { TUTORIAL_STEPS } from '../src/frontend/tutorial';

function engineFor(source: string, random = () => 0.5) {
  const program = new ASTBuilder().build(new Parser(source).parse());
  validateAST(program);
  return createEngine(buildGame(program), { width: 16, height: 16, random }, createEvaluator());
}

const at = (engine: ReturnType<typeof engineFor>, type: string) =>
  engine.snapshot().elements.filter((e) => e.elementType === type);

test('random() returns whole numbers inside the range', () => {
  const values = [0, 0.4, 0.999].map((r) => {
    const engine = engineFor(
      'element Dot:\n\thas value\n\thas function tick:\n\t\tlet value be random(-1, 1)\n\t\tlet position_x be position_x + value\n',
      () => r,
    );
    engine.place('Dot', 5, 5);
    return engine.step().elements[0].x;
  });
  expect(values).toEqual([4, 5, 6]);
});

test('chance() compares against a percentage', () => {
  const source = 'element Dot:\n\thas function tick:\n\t\tif chance(30):\n\t\t\tdisappear()\n';
  const low = engineFor(source, () => 0.2);
  low.place('Dot', 1, 1);
  expect(low.step().elements).toHaveLength(0);
  const high = engineFor(source, () => 0.5);
  high.place('Dot', 1, 1);
  expect(high.step().elements).toHaveLength(1);
});

test('place_element() spawns anywhere and skips occupied or outside cells', () => {
  const engine = engineFor(
    'element Seed:\n\thas function tick:\n\t\tplace_element(Leaf, grid_width() - 1, 0)\n\t\tplace_element(Leaf, 99, 99)\n\nelement Leaf:\n\thas color with Color(#22aa44)\n',
  );
  engine.place('Seed', 3, 3);
  engine.step();
  engine.step();
  expect(at(engine, 'Leaf').map((e) => [e.x, e.y])).toEqual([[15, 0]]);
});

test('is_empty() treats the grid edge as not empty', () => {
  const engine = engineFor(
    'element Sand:\n\thas function tick:\n\t\tif is_empty(position_x, position_y + 1):\n\t\t\tlet position_y be position_y + 1\n',
  );
  engine.place('Sand', 2, 13);
  for (let i = 0; i < 5; i++) engine.step();
  expect(at(engine, 'Sand')[0].y).toBe(15);
});

test('swap_with() and family type checks let sand sink through water', () => {
  const engine = engineFor(
    'template_element Liquid:\n\thas color\n\nelement Water is like Liquid:\n\thas color with Color(#0000ff)\n\nelement Sand:\n\thas function tick:\n\t\tlet below be get_element_at(position_x, position_y + 1)\n\t\tif below is Liquid:\n\t\t\tswap_with(below)\n',
  );
  engine.place('Sand', 4, 4);
  engine.place('Water', 4, 5);
  engine.step();
  expect(at(engine, 'Sand')[0].y).toBe(5);
  expect(at(engine, 'Water')[0].y).toBe(4);
});

test('every preset and tutorial step compiles and runs', () => {
  for (const source of [...PRESETS.map((p) => p.source), ...TUTORIAL_STEPS.map((s) => s.source)]) {
    const engine = engineFor(source, Math.random);
    for (const name of engine.availableElements()) {
      for (let x = 0; x < 16; x += 3) {
        try {
          engine.place(name, x, 2 + (x % 5));
        } catch {
          // occupied cell: fine
        }
      }
    }
    for (let i = 0; i < 30; i++) engine.step();
  }
});
